{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Clobazam, a 1,5-benzodiazepine with a chloro-substituted ring, has 90% oral bioavailability in fasted healthy volunteers; its high transfer score (0.9907) and shared benzodiazepine scaffold support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Estazolam, a triazolobenzodiazepine with a 5-phenyl and 7-chloro pattern, has 87% oral bioavailability in healthy volunteers; high transfer score (0.9894) supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Alprazolam sustained-release absolute bioavailability was >0.84 versus IV in healthy volunteers; high transfer score (0.9891) and the same benzodiazepine core support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Adinazolam, a benzodiazepine with a chloro-phenyl and basic side chain, has absolute F of 39% in healthy male volunteers; although lower than other analogues, it remains above the 20% threshold and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Tolvaptan, despite a different scaffold, has absolute F of 56% in healthy subjects and a high transfer score (0.9892), providing additional evidence that high F is achievable for this property class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 1,4-benzodiazepine N-oxide (chlordiazepoxide-like). High-transfer benzodiazepine analogues—clobazam (90%), estazolam (87%), alprazolam (>84%), and adinazolam (~40%)—all have oral bioavailability above 20%, and the physicochemical prior is favorable. Low-transfer records are not applicable. Therefore predict high F.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule was provided.",
    "The effect of the N-oxide and amidine groups on first-pass metabolism is not directly measured, but close high-transfer analogues support high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

